// Validate Facebook X-Hub-Signature-256 HMAC.
// Reject the request immediately if the signature is missing or mismatched —
// this prevents anyone spoofing Facebook from triggering our pipeline.
const crypto = require('crypto');

const appSecret = $env.MESSENGER_APP_SECRET;
if (!appSecret) {
  throw new Error('MESSENGER_APP_SECRET env var is not configured in n8n.');
}

const sig = $input.first().json.headers['x-hub-signature-256'] || '';
const rawBody = $input.first().json.body || '';
const expected = 'sha256=' + crypto.createHmac('sha256', appSecret).update(rawBody).digest('hex');

if (sig.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected))) {
  throw new Error('Invalid X-Hub-Signature-256');
}

// Parse the FB envelope and emit one item per message event.
const parsed = JSON.parse(rawBody);
const out = [];
for (const entry of (parsed.entry || [])) {
  for (const ev of (entry.messaging || [])) {
    if (!ev.message || !ev.message.text) continue;
    out.push({
      json: {
        user_id: ev.sender.id,
        page_id: entry.id,
        message_text: ev.message.text,
        timestamp: Math.floor((ev.timestamp || Date.now()) / 1000),
        correlation_id: `fb_${ev.message.mid || crypto.randomUUID()}`
      }
    });
  }
}
return out;
